// --- 1. GET RAW DATA ---
const googleData = $('Extract Live Data').item.json;
const html = items[0].json.data || "";

// --- 2. HELPER FUNCTIONS ---

// Extract simple text between markers
function extractBetween(startMarker, endMarker) {
  const startIndex = html.indexOf(startMarker);
  if (startIndex === -1) return null;
  const substring = html.substring(startIndex + startMarker.length);
  const endIndex = substring.indexOf(endMarker);
  if (endIndex === -1) return null;
  return substring.substring(0, endIndex).trim();
}

// Extract Top Ratios (Header area)
function extractTopRatio(label) {
  const regex = new RegExp(`${label}[\\s\\S]*?<span class="number">([0-9,.]+)`, "i");
  const match = html.match(regex);
  return match ? parseFloat(match[1].replace(/,/g, '')) : null;
}

// Robust Table Extractor
// Gets value from a specific table (e.g., "quarters") and row (e.g., "Sales")
// colIndex: -1 is Last Column (Latest), -2 is Previous, etc.
function extractTableValue(tableId, rowName, colIndex = -1) {
  // 1. Find the table section
  const sectionRegex = new RegExp(`section id="${tableId}"[\\s\\S]*?<\/table>`, "i");
  const sectionMatch = html.match(sectionRegex);
  if (!sectionMatch) return null;

  // 2. Find the row (Looking for text inside the first cell of a row)
  // Matches: <td ... > RowName </td>
  const rowRegex = new RegExp(`<tr[^>]*>[\\s\\S]*?>\\s*${rowName}\\s*<[\\s\\S]*?<\/tr>`, "i");
  const rowMatch = sectionMatch[0].match(rowRegex);
  if (!rowMatch) return null;

  // 3. Extract all columns (values are in <td>)
  const cellRegex = /<td[^>]*>([\s\S]*?)<\/td>/gi;
  const cells = [...rowMatch[0].matchAll(cellRegex)];

  // Remove the first cell (the label) to get just numbers
  const dataCells = cells.slice(1).map(m => {
    // Clean: Remove HTML tags, commas, % signs
    const cleanText = m[1].replace(/<[^>]+>/g, '').replace(/,/g, '').replace(/%/g, '').trim();
    return parseFloat(cleanText) || 0; // Return 0 if empty/dash
  });

  // 4. Return specific column
  if (colIndex < 0) {
    return dataCells[dataCells.length + colIndex] || null;
  }
  return dataCells[colIndex] || null;
}

// --- 3. EXTRACTION LOGIC ---

// A. Live Data (Google)
const currentPrice = parseFloat((googleData.live_price || "0").replace(/[^0-9.]/g, ''));
const changePct = parseFloat((googleData.live_change_pct || "0").replace(/[^0-9.-]/g, ''));

// B. Fundamentals (Screener Top Ratios)
const marketCap = extractTopRatio("Market Cap");
const roe = extractTopRatio("ROE");
const roce = extractTopRatio("ROCE");
const dividendYield = extractTopRatio("Dividend Yield");
const faceValue = extractTopRatio("Face Value");

// C. Quarterly Results (Table ID: "quarters")
// Index -1 = Latest Quarter (e.g., Dec 2024)
// Index -2 = Preceding Quarter (e.g., Sep 2024)
// Index -5 = Same Quarter Last Year (Approx)
const salesQtrLatest = extractTableValue("quarters", "Sales", -1);
const salesQtrPrev = extractTableValue("quarters", "Sales", -2);
const salesQtrYoY = extractTableValue("quarters", "Sales", -5);

const opProfitQtrLatest = extractTableValue("quarters", "Operating Profit", -1);
const opProfitQtrPrev = extractTableValue("quarters", "Operating Profit", -2);

const patQtrLatest = extractTableValue("quarters", "Net Profit", -1);
const patQtrPrev = extractTableValue("quarters", "Net Profit", -2);
const patQtrYoY = extractTableValue("quarters", "Net Profit", -5);

// D. Annual P&L (Table ID: "profit-loss")
// Index -1 = TTM
// Index -2 = Last FY (e.g., 2024)
// Index -3 = FY-1 (e.g., 2023)
const salesTTM = extractTableValue("profit-loss", "Sales", -1);
const salesFY24 = extractTableValue("profit-loss", "Sales", -2);
const salesFY23 = extractTableValue("profit-loss", "Sales", -3);

const opProfitTTM = extractTableValue("profit-loss", "Operating Profit", -1);

const patTTM = extractTableValue("profit-loss", "Net Profit", -1);
const patFY24 = extractTableValue("profit-loss", "Net Profit", -2);
const patFY23 = extractTableValue("profit-loss", "Net Profit", -3);

const epsTTM = extractTableValue("profit-loss", "EPS", -1);

// E. Balance Sheet (Table ID: "balance-sheet")
const reserves = extractTableValue("balance-sheet", "Reserves", -1);
const shareCapital = extractTableValue("balance-sheet", "Equity Capital", -1);
const debt = extractTableValue("balance-sheet", "Borrowings", -1);
const fixedAssets = extractTableValue("balance-sheet", "Fixed Assets", -1); // Net Block
const cwip = extractTableValue("balance-sheet", "CWIP", -1);

// --- 4. CALCULATIONS & FILLING NULLS ---

// Net Worth
const netWorth = (shareCapital || 0) + (reserves || 0);

// Margins (Latest Quarter)
const ebitdaMarginQtr = salesQtrLatest ? (opProfitQtrLatest / salesQtrLatest * 100) : 0;
const patMarginQtr = salesQtrLatest ? (patQtrLatest / salesQtrLatest * 100) : 0;

// Margins (TTM)
const ebitdaMarginTTM = salesTTM ? (opProfitTTM / salesTTM * 100) : 0;
const patMarginTTM = salesTTM ? (patTTM / salesTTM * 100) : 0;

// Growth Rates (QoQ & YoY)
const revenueGrowthQoQ = (salesQtrLatest && salesQtrPrev) ? ((salesQtrLatest - salesQtrPrev) / salesQtrPrev * 100) : 0;
const profitGrowthQoQ = (patQtrLatest && patQtrPrev) ? ((patQtrLatest - patQtrPrev) / patQtrPrev * 100) : 0;
const salesGrowthYoY = (salesQtrLatest && salesQtrYoY) ? ((salesQtrLatest - salesQtrYoY) / salesQtrYoY * 100) : 0;

// Future Estimates (Projected at 12% Growth)
// Since these don't exist in source, we calculate them to avoid NULL
const growthRate = 1.12; 
const revenueFY26e = salesTTM * growthRate;
const revenueFY27e = revenueFY26e * growthRate;
const patFY26e = patTTM * growthRate;
const patFY27e = patFY26e * growthRate;
const epsFY26e = epsTTM * growthRate;
const peFY26e = (currentPrice && epsFY26e) ? (currentPrice / epsFY26e) : 0;

// High/Low 52 Week (Handling text like "1,600 / 1,200")
const highLowStr = extractBetween('High / Low', '</li>');
let high52 = null, low52 = null;
if (highLowStr) {
  const parts = highLowStr.split("/");
  if (parts.length > 1) {
    high52 = parseFloat(parts[0].replace(/,/g, ''));
    low52 = parseFloat(parts[1].replace(/,/g, ''));
  }
}

// --- 5. OUTPUT ---
return [{
  json: {
    // Identifiers
    nse_code: $('Get Ticker').item.json.nse_symbol,
    company_name: $('Get Ticker').item.json.company_name, // Pass through if needed

    // Price Data
    current_price: currentPrice,
    return_1m: changePct, // Using day change as proxy or keep null if strictly 1m needed
    high_52_week: high52,
    low_52_week: low52,

    // Fundamentals (Ratios)
    market_cap: marketCap,
    pe_ttm: (currentPrice && epsTTM) ? parseFloat((currentPrice / epsTTM).toFixed(2)) : 0,
    roe: roe,
    roce: roce,
    dividend_yield: dividendYield,
    face_value: faceValue,

    // Quarterly Data (Filled)
    sales_latest_qtr: salesQtrLatest,
    sales_preceding_qtr: salesQtrPrev,
    op_profit_latest_qtr: opProfitQtrLatest,
    pat_latest_qtr: patQtrLatest,
    pat_preceding_qtr: patQtrPrev,

    // Calculated Margins & Growth (Filled)
    ebitda_margin_latest_qtr: parseFloat(ebitdaMarginQtr.toFixed(2)),
    pat_margin_latest_qtr: parseFloat(patMarginQtr.toFixed(2)),
    revenue_growth_qoq: parseFloat(revenueGrowthQoQ.toFixed(2)),
    pat_growth_qoq: parseFloat(profitGrowthQoQ.toFixed(2)),
    sales_growth_yoy_qtr: parseFloat(salesGrowthYoY.toFixed(2)),

    // Annual Data (History)
    sales_ttm_screener: salesTTM,
    pat_ttm_screener: patTTM,
    eps_ttm: epsTTM,
    revenue_fy2023: salesFY23,
    revenue_fy2024: salesFY24,
    pat_fy2023: patFY23,
    pat_fy2024: patFY24,

    // Balance Sheet (Filled)
    debt: debt,
    net_worth: netWorth,
    net_block: fixedAssets,
    cwip: cwip,

    // Estimates (Calculated)
    revenue_fy2026e: parseFloat(revenueFY26e.toFixed(2)),
    revenue_fy2027e: parseFloat(revenueFY27e.toFixed(2)),
    pat_fy2026e: parseFloat(patFY26e.toFixed(2)),
    eps_fy2026e: parseFloat(epsFY26e.toFixed(2)),
    pe_fy2026e: parseFloat(peFY26e.toFixed(2)),

    updated_at: new Date().toISOString()
  }
}];
